class UnsafeMemory {
    private var unsafePointer: UnsafeMutableBufferPointer<Int>?

    init(size: Int) {
        unsafePointer = UnsafeMutableBufferPointer(start: calloc(size, MemoryLayout<Int>.stride), count: size)
    }

